  Lemma r_kob : forall (v f : Z) (hc : HST asegs R HIA) (LBc : list blk) (mc : mem) (dXc : mpd)
      (xra xt0 xt1 xt2 xa1 xa2 xa3 xa4 xa5 xa6 xa7 xs2 xt3 xt4 xt5 xt6 : word),
    XJA asegs R HIA h LB LF m dX sp lo 32 KFRAME [] v f hc LBc mc dXc ->
    md_own dXc = LHeap -> 12 <= md_n dXc ->
    (forall ws r, -2^31 < r <= 0 -> r <> MBEDTLS_ERR_MPI_ALLOC_FAILED -> reducer_R 12 dX LB r (relimb dXc ws)) ->
    v <= grow_PHI 12 -> f <= red_FRn d ->
    aevtA asegs (KF asegs R HIA hc mo) KPOST
      (MS (mkR xra (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp xt0 xt1 xt2 (Z_to_bv 64 X) (Z_to_bv 64 (al_sb (arl_AL R))) (Z_to_bv 64 0)
               xa1 xa2 xa3 xa4 xa5 xa6 xa7 xs2 s3 s4 s5 s6 s7 s8 s9 s10 s11 xt3 xt4 xt5 xt6) F (Z_to_bv 64 0xd67e8) fc None mc (seg_rom asegs)).
  Proof.
    intros until xt6; intros J0 EO HNK HR0 BV BF.
    jc_open; pose proof (jca_facts asegs R HIA h LB LF m dX sp lo 32 KFRAME JC) as (LO0 & LOSP & SP64 & ALO' & ACP' & X0 & X16 & XAL & DSX & LEN & NR).
    basic_factsA hc.
    pose proof (xa_facts _ _ _ _ _ _ _ _ _ _ _ _ JC _ _ _ _ _ _ _ J0) as (ND1 & LEN1 & NR1 & SG1 & CX1 & OWN0 & OWN1).
    pose proof J0 as [MI1 ST1 FR1 HH1 HT1 HS1 HF1 HCS1 HV1 HFR1 MX1 AD1 PD1 NSc OUT1 FRS1 FRA1 HPX1 OX1 XP1 XLS1 NM1]. cbn [app] in HH1.
    ddestruct (OWN1 ltac:(rewrite EO; discriminate)) as (_ & N1 & XIN & XPAL & XARR & P0 & PC & PI & OP & P47).
    pose proof (hm_top asegs R HIA hc LBc LF mc HH1) as HTOP.
    assert (SCS : crange (hcs asegs R HIA hc) lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| clear - LOS; lia| rewrite HS1; pose proof (hm_top asegs R HIA h LB LF m HH); clear - H TOP; lia]).
    pose proof (AIh_laws asegs R HIA hc) as LAWS; pose proof (KF_kinv asegs R HIA hc mo) as KINV.
    unfold mpi_cells in CX1.
    pose proof (conj J0 I) as J0box. clear J0 HV1 HFR1 FRS1 FRA1 HPX1 OUT1 NM1 MX1 XP1 XLS1 NSc HCS1 HF1 OWN0 OWN1.
  (* [comment removed for export] *)
    pose proof (hm_abase asegs R HIA hc LBc LF mc HH1) as ABm. pose (lxi := lxA_img (arl_AL R) IMG).
    lx_pre. lx_run_tac (PLAN [0xd7184] [] 80%N).
    lx_tree.
    lazymatch goal with E : ?mx = mc |- _ => subst mx end.
    destruct J0box as [J0 _].
    assert (KS : koblitz_stmtB asegs R HIA A_ECP_KOBLITZ).
    { apply A_ecp_koblitz_spec; first [ exact IMG | exact NS1 | exact NEEDR | exact CMUL | exact (A_mpi_core_add_spec (arl_AL R) IMG)
          | rewrite UARG; reflexivity | rewrite SM2; reflexivity | rewrite AMS; reflexivity | rewrite AMC; reflexivity ]. }
    assert (PR : forall a, A_RP_P192K1 <= a < A_RP_P192K1 + 8 -> rtc_prist a).
    { intros a Ha. unfold rtc_prist, rtc_pristine. do 2 apply Exists_cons_tl. apply Exists_cons_hd. cbn [fst snd]. unfold A_RP_P192K1 in Ha. clear - Ha. lia. }
    pose proof (PRIMG _ (PR A_RP_P192K1 ltac:(clear; lia))) as RK1. pose proof (PRIMG _ (PR (A_RP_P192K1 + 7) ltac:(clear; lia))) as RK2.
    assert (RTAB : koblitz_rtabB asegs R HIA A_RP_P192K1 [Z_to_bv 64 0x11c9; Z_to_bv 64 0x1]).
    { unfold koblitz_rtabB. split; [reflexivity|]. split; [unfold A_RP_P192K1; clear; lia|]. split; [unfold A_RP_P192K1; reflexivity|].
      split; [clear - RK1; lia|]. split; [clear - RK2; lia|].
      intros hq LBq LFq mq HHq. split.
      - pose proof (asan_rtc_const mq A_RP_P192K1 (u32s [Z_to_bv 64 0x11c9; Z_to_bv 64 0x1]) (RTC mq (hm_rtc asegs R HIA hq _ _ mq HHq)) ltac:(vm_compute; reflexivity) ltac:(vm_compute; reflexivity)) as RO.
        destruct RO as [_ Hb]. cbn [cells_bytes cbytes] in Hb. rewrite app_nil_r in Hb. exact Hb.
      - eapply (AImgGlobals.aobj_img asegs (arl_AL R)); [apply (A_mpi_copy.hcs_img_cs_cp R HIA IMG)| eapply (hm_img_shadow asegs R HIA); exact HHq| vm_compute; reflexivity]. }
    assert (RPLO : A_RP_P192K1 + 8 <= lo).
    { pose proof (alloc_ceiling_lo (L := arl_L R)) as ACL. unfold A_RP_P192K1. clear - ACL ALO LOS. lia. }
    unfold koblitz_stmtB in KS.
    eapply (aevtA_cut_evtA_KF asegs R HIA hc mo).
    { eapply KS with (h := hc) (LB := LBc) (LF := LF) (X := md_p dXc) (XB := 4 * md_n dXc) (RP := A_RP_P192K1) (bits := 192) (lo := lo)
                     (xs := md_limbs dXc) (rs := [Z_to_bv 64 0x11c9; Z_to_bv 64 0x1]);
        rewrite ?(unsigned_lit (bv_unsigned sp + -32)) by (clear - SPR SLO2 LOS ALO ACP NER NEEDR; lia).
      all: try first [ exact HH1 | exact LFB | exact XARR | exact XIN | exact RTAB | exact RPLO | exact LOS | exact TPV | exact MI1 | exact ST1 ].
      all: try (left; reflexivity); try (right; left; reflexivity); try (right; right; reflexivity).
      all: try (unfold koblitz_xl; rewrite LEN1; change (192 / 16) with 12; clear - HNK; lia).
      all: try (rewrite LEN1; clear; lia).
      all: try (clear - XPAL; Z.div_mod_to_equations; lia).
      all: try (unfold KOBLITZ_STACK; clear - SLO2; lia).
      all: try (rewrite HT1; clear - TOP; lia).
      all: try (clear - SPA; Z.div_mod_to_equations; lia).
      all: try (unfold A_RP_P192K1; reflexivity).
      all: try reflexivity.
      all: try (vm_compute; reflexivity).
      all: match goal with |- ?g => idtac "KOB-PRE-LEFT:" g end. }
    intros ms' PO. unfold koblitz_postB in PO.
    destruct PO as (k0 & k1 & k2 & ka0 & ka1 & ka2 & ka3 & ka4 & ka5 & ka6 & ka7 & k3 & k4 & k5 & k6 & m' & h' & xs'
                    & E & ARR' & LEN' & HCS' & HT' & HS' & HF' & HV' & HFR' & HKI & HH' & PW & MI' & ST').
    subst ms'.
    lazymatch goal with |- aevtA _ _ _ (MS _ _ (ret_pc (Z_to_bv 64 ?x)) _ _ _ _) =>
      replace (ret_pc (Z_to_bv 64 x)) with (Z_to_bv 64 x) by (symmetry; apply ret_pc_even; [ lia | reflexivity ]) end.
    rewrite ?(unsigned_lit (bv_unsigned sp + -32)) in PW, ST' by (clear - SPR SLO2 LOS ALO ACP NER NEEDR; lia).
    pose proof (xa_kob asegs R HIA h LB LF m dX sp lo 32 KFRAME JC [] v f hc LBc mc dXc (koblitz_xl 192) m' h' xs' J0 EO
                  ltac:(unfold koblitz_xl; change (192 / 16) with 12; clear - HNK; lia) MI' ST' PW HCS' HT' HS' HF' HV' HFR' HH' ARR' LEN') as J2.
    intros mo1 [HK1 MF1]. apply (aevtA_enter asegs (KF asegs R HIA h' mo) _ _ mo1 (conj (proj2 (HKI mo1) HK1) MF1)).
    clear LAWS KINV. pose proof (AIh_laws asegs R HIA h') as LAWS. pose proof (KF_kinv asegs R HIA h' mo) as KINV.
    pose proof (munch_refl ([] : list ivl) m') as MU. pose proof (wmono_refl asegs m') as WM.
    zstep.
    eapply r_ret with (r := 0); [exact J2| apply HR0; [clear; lia| unfold MBEDTLS_ERR_MPI_ALLOC_FAILED; clear; lia]| exact BV| exact BF].
  Qed.
